import{c as e,Q as o,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"12-Rule Canon 深化研究 — 論文接地的全面改寫","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-05-12-rule-deepened-research.md","filePath":"research/reports/2026-06-05-12-rule-deepened-research.md","lastUpdated":1780842316000}'),a={name:"research/reports/2026-06-05-12-rule-deepened-research.md"};function s(i,t,l,g,c,d){return o(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="_12-rule-canon-深化研究-—-論文接地的全面改寫" tabindex="-1">12-Rule Canon 深化研究 — 論文接地的全面改寫 <a class="header-anchor" href="#_12-rule-canon-深化研究-—-論文接地的全面改寫" aria-label="Permalink to &quot;12-Rule Canon 深化研究 — 論文接地的全面改寫&quot;">​</a></h1><blockquote><p><strong>產出日期</strong>：2026-06-05 <strong>分支</strong>：<code>feature/karpathy-mnilax-operational-layer</code><strong>任務</strong>：以 Karpathy R1–R4 + Mnilax R5–R12 為基線，回到「原始 12 條準則本身」做深入發想與延伸改寫，每處延伸都以論文指引／借鏡／引用接地，並把 7 個運行維度（Prompt Caching / Context Management / Agent Teams / Sub-Agent / Memory Management / LLM 自我演化 / Harness Engineering）融入各條規則的深化，而非疊加為獨立矩陣。 <strong>配對產物</strong>：<code>2026-06-05-12-rule-deepened-ruleset.md</code>（可直接部署的改寫準則全文） <strong>基線報告</strong>：本研究承接 #465（universalization-research）/ #466（雙版成品 + TESTBANK），定位為「<strong>深化層</strong>」——前作做通用化與可部署化，本作做<strong>論文發想延伸</strong>。</p></blockquote><hr><h2 id="_0-框架誠實聲明-讀本報告前必讀" tabindex="-1">0. 框架誠實聲明（讀本報告前必讀） <a class="header-anchor" href="#_0-框架誠實聲明-讀本報告前必讀" aria-label="Permalink to &quot;0. 框架誠實聲明（讀本報告前必讀）&quot;">​</a></h2><ol><li><strong>基線數字是作者自報，非同儕審查</strong>：Karpathy「41%→11%」與 Mnilax「41%→3%（30 codebases / 6 weeks / 50 tasks）」皆為作者在 GitHub / X 上的個人聲明，<strong>無公開方法論、無控制組、無同儕審查</strong>。廣泛轉載 ≠ 獨立驗證。本報告引用時一律標 <strong>作者自報 / LOW-MEDIUM</strong>。</li><li><strong>論文接地是「平行失敗模式」非「同一性」</strong>：本研究引用的論文多來自 agent / memory / multi-agent 領域，與「單一 coding assistant 紀律」<strong>不是同一個系統</strong>。論文證據的角色是「在不同層級觀察到平行的失敗模式」，提供 empirical 背書與機制借鏡，<strong>不是證明這些規則本身</strong>。</li><li><strong>mapping 信度三分級</strong>：每條「論文 → 規則」對應標 <strong>Direct</strong>（論文直接證明此規則的失敗模式或機制）/ <strong>Analogous</strong>（不同領域但失敗模式平行）/ <strong>Inferential</strong>（需推理跳躍）。grep 證明「數字存在」≠ 證明「數字接地此規則」（Lesson 2026-06-04-G）。需要 hedge 字眼的對應一律降級或剔除。</li><li><strong>社群最佳實踐分官方與軼事</strong>：官方 Anthropic docs 標 HIGH；部落格 / Reddit 軼事標 LOW；唯一接近系統性的跨 repo 數據（AGENTS.md 2,500+ repo）原始方法論未公開，標 MEDIUM。</li></ol><hr><h2 id="_1-任務與基線" tabindex="-1">1. 任務與基線 <a class="header-anchor" href="#_1-任務與基線" aria-label="Permalink to &quot;1. 任務與基線&quot;">​</a></h2><h3 id="_1-1-原始-12-條的來源鏈" tabindex="-1">1.1 原始 12 條的來源鏈 <a class="header-anchor" href="#_1-1-原始-12-條的來源鏈" aria-label="Permalink to &quot;1.1 原始 12 條的來源鏈&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026-01 Karpathy X thread（抱怨 Claude 寫碼 3 大失敗模式）</span></span>
<span class="line"><span>   └→ Forrest Chang 封裝成 4 條行為規則 CLAUDE.md（65 行）→ GitHub 爆紅（作者自報 120k stars）</span></span>
<span class="line"><span>        └→ Mnilax 在 30 codebases / 6 weeks 實測 → 確認 4 條有效（41%→&lt;3% on tasks playing to strengths）</span></span>
<span class="line"><span>             └→ 補 8 條（R5–R12）涵蓋 2026-05 的 agent 編排問題 → 12 條</span></span>
<span class="line"><span>                  └→ cc-workspace 落為 §R1–§R12 強制條文（AB4.0 基線，workspace 耦合）</span></span>
<span class="line"><span>                       └→ #465/#466 通用化 + 雙版成品</span></span>
<span class="line"><span>                            └→ 【本研究】論文接地的深化延伸改寫</span></span></code></pre></div><h3 id="_1-2-mnilax-原文揭示的「為何補-8-條」-親取自-x-article-12-397-字元" tabindex="-1">1.2 Mnilax 原文揭示的「為何補 8 條」（親取自 X article，12,397 字元） <a class="header-anchor" href="#_1-2-mnilax-原文揭示的「為何補-8-條」-親取自-x-article-12-397-字元" aria-label="Permalink to &quot;1.2 Mnilax 原文揭示的「為何補 8 條」（親取自 X article，12,397 字元）&quot;">​</a></h3><p>每條 R5–R12 都來自一個具體失敗時刻（&quot;the moment&quot;），這是基線文件最有價值卻最少被轉載的部分：</p><table tabindex="0"><thead><tr><th>規則</th><th>Mnilax 的 the moment（親取原文摘要）</th></tr></thead><tbody><tr><td>R5</td><td>用 Claude「決定 503 是否重試」運作兩週後開始 flaky——模型把 request body 當決策 context，retry policy 變隨機</td></tr><tr><td>R6</td><td>一次 debug session 跑 90 分鐘，模型在同一個 8KB error message 上反覆迭代，最後建議的修法是 40 條訊息前已被拒絕的；token budget 會在第 12 分鐘殺掉它</td></tr><tr><td>R7</td><td>codebase 有兩種 error-handling pattern，Claude 寫的新碼兩種都做 → 雙重 handler，error 被吞兩次，花 30 分鐘才查出</td></tr><tr><td>R8</td><td>Claude 在一個它沒讀過的同功能函式旁加了一個一模一樣的函式，因 import order 新的覆蓋舊的，而舊的當了 6 個月 source of truth</td></tr><tr><td>R9</td><td>Claude 為 auth 函式寫 12 個測試全過，但 production auth 壞了——測試只測「有回傳」不測「回傳對的」，函式回傳常數也能過</td></tr><tr><td>R10</td><td>6 步 refactor 在第 4 步出錯，等發現時 Claude 已在壞狀態上做完第 5、6 步，解纏比重做還久</td></tr><tr><td>R11</td><td>Claude 把 React hooks 引進 class-component codebase，能跑但破壞了假設 componentDidMount 的測試模式，花半天移除重寫</td></tr><tr><td>R12</td><td>Claude 說 migration「completed successfully」，實際靜默跳過 14% 違反 constraint 的紀錄，11 天後報表異常才發現</td></tr></tbody></table><h3 id="_1-3-mnilax-的-6-個「what-didn-t-work」-反面教訓-是改寫的負面約束" tabindex="-1">1.3 Mnilax 的 6 個「what didn&#39;t work」（反面教訓，是改寫的負面約束） <a class="header-anchor" href="#_1-3-mnilax-的-6-個「what-didn-t-work」-反面教訓-是改寫的負面約束" aria-label="Permalink to &quot;1.3 Mnilax 的 6 個「what didn&#39;t work」（反面教訓，是改寫的負面約束）&quot;">​</a></h3><ol><li><strong>抄 Reddit/X 的規則</strong> → 多半是 R1–R4 換句話說，或不通用的 domain-specific（「always use Tailwind」）→ 砍。</li><li><strong>超過 12 條</strong> → 測到 18 條，合規率 76%→52%（過 14 條開始崩）。200 行天花板真實存在。</li><li><strong>依賴可能不存在的工具</strong>（「always use eslint」eslint 沒裝就靜默失敗）→ 改 capability-agnostic 措辭（「match the codebase&#39;s enforced style」）。</li><li><strong>放 examples 而非 rules</strong> → 3 個 example ≈ 10 條 rule 的 context 成本，且模型 over-fit。用 rule 不用 example。</li><li><strong>「be careful」「think hard」「really focus」</strong> → 純噪音，合規率掉到 ~30%（不可測）→ 換成具體祈使句（「state assumptions explicitly」）。</li><li><strong>叫 Claude 當「senior」</strong> → 沒用，Claude 已自認 senior；gap 在「想 vs 做」之間，imperative rule 能補，identity prompt 不能。</li></ol><blockquote><p><strong>對改寫的直接含義</strong>：深化 ≠ 加規則數。深化必須在「保持 ≤12 條主規則」前提下，把每條的<strong>機制、邊界、可驗證條件、反模式</strong>寫深，並用 capability-agnostic + imperative + testable 措辭。這正是把運行維度「融入」而非「疊加」的根本原因。</p></blockquote><h3 id="_1-4-mnilax-自承的-4-個斷裂點-karpathy-4-條的-gap-是深化的切入點" tabindex="-1">1.4 Mnilax 自承的 4 個斷裂點（Karpathy 4 條的 gap，是深化的切入點） <a class="header-anchor" href="#_1-4-mnilax-自承的-4-個斷裂點-karpathy-4-條的-gap-是深化的切入點" aria-label="Permalink to &quot;1.4 Mnilax 自承的 4 個斷裂點（Karpathy 4 條的 gap，是深化的切入點）&quot;">​</a></h3><ol><li><strong>長時運行 agent 任務</strong>：R1–R4 只針對「正在寫碼的瞬間」，對 multi-step pipeline 沉默 → pipeline drift（R6/R10/R12 補）。</li><li><strong>多 codebase 一致性</strong>：「match existing style」假設只有一種 style，monorepo 12 服務時隨機挑或平均（R7/R11 補）。</li><li><strong>測試品質</strong>：Goal-Driven 把「tests pass」當成功，沒說測試要有意義（R9 補）。</li><li><strong>production vs prototype</strong>：同一套 Simplicity 規則保護 production 卻拖慢正當需要 100 行 scaffold 探方向的 prototype（R2 的情境化）。</li></ol><hr><h2 id="_2-源頭校驗-primary-source-discipline" tabindex="-1">2. 源頭校驗（primary-source discipline） <a class="header-anchor" href="#_2-源頭校驗-primary-source-discipline" aria-label="Permalink to &quot;2. 源頭校驗（primary-source discipline）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>來源</th><th>取得方式</th><th>信度</th><th>備註</th></tr></thead><tbody><tr><td>Karpathy CLAUDE.md（R1–R4）</td><td>WebFetch raw.githubusercontent（SDD cache hit，304 unchanged）</td><td>文件親驗 HIGH；數字 LOW</td><td>文件本身無 Karpathy quote、無方法論 metadata</td></tr><tr><td>Mnilax article（R5–R12 + moments）</td><td>fxtwitter API 親取（12,397 字元 Draft.js blocks）</td><td>文件親驗 HIGH；數字 LOW</td><td>X 本體需登入；fxtwitter 為公開鏡像</td></tr><tr><td>12 篇 memory/演化論文</td><td>researcher sub-agent 讀 .md + grep 親驗數字</td><td>數字 HIGH；mapping 見 §3 分級</td><td>MemGPT/Reflexion/Voyager 等數字逐句 grep</td></tr><tr><td>MAST 14 失敗模式 + κ=0.88</td><td>sub-agent grep <code>2503-13657.md</code> 原文</td><td>HIGH</td><td>κ=0.88 <strong>第三度親驗 = inter-annotator agreement，非 spec-quality</strong></td></tr><tr><td>社群/官方最佳實踐</td><td>sub-agent WebSearch + WebFetch</td><td>官方 HIGH / 軼事 LOW</td><td>詳見 §6</td></tr></tbody></table><hr><h2 id="_3-12-條規則的論文接地深化分析" tabindex="-1">3. 12 條規則的論文接地深化分析 <a class="header-anchor" href="#_3-12-條規則的論文接地深化分析" aria-label="Permalink to &quot;3. 12 條規則的論文接地深化分析&quot;">​</a></h2><blockquote><p>每條格式：<strong>原則回顧 → 論文深化（含信度）→ 延伸的新子條/邊界 → 可機械驗證條件 → 反模式</strong>。 這一節是研究分析；可部署的精煉版見配對 ruleset 檔。</p></blockquote><h3 id="r1-—-think-before-coding-深化-規格模糊度是天花板" tabindex="-1">R1 — Think Before Coding（深化：規格模糊度是天花板） <a class="header-anchor" href="#r1-—-think-before-coding-深化-規格模糊度是天花板" aria-label="Permalink to &quot;R1 — Think Before Coding（深化：規格模糊度是天花板）&quot;">​</a></h3><p><strong>原則</strong>：不假設、不藏困惑、浮現 tradeoff；多解釋列選項不靜默選。</p><p><strong>論文深化</strong>：</p><ul><li><strong>MAST FM-7「Fail to ask for clarification」</strong>（Direct）：MAST 跨 7 框架 200+ 任務發現，「面對不清楚/不完整資料時無法請求補充資訊，導致錯誤行動」是 14 失敗模式之一。<strong>一句零 hedge</strong>：多 agent 架構層的「不清楚不問」與 assistant 紀律層的「沉默假設」是同一失敗在不同層的投影，MAST 提供跨框架 empirical 背書。</li><li><strong>MetaGPT SOP 結構化 → token 效率 124.3 vs ChatDev 248.9 tokens/loc（省 ~50%）</strong>（Direct，數字親驗 <code>2308-00352.md</code>）：規格（角色/任務的結構化定義）的明確度決定 multi-agent 系統的效率天花板；<strong>前期投資精確規格比加 agent 數量更有效</strong>。<strong>一句零 hedge</strong>：結構化規格使 token 效率翻倍，與 R1「假設顯露、列選項確認」同向。〔註：原稿引「任務完成時間 −40%」係轉引自 Anthropic 官方工具描述改良資料，非 MetaGPT 論文數字，已替換為論文可親驗的 token 效率數字；−40% 改標為「Anthropic 官方資料（二手引用，LOW）」見 §5。〕</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R1.1 規格模糊度優先於運算資源</strong>：遇模糊先釐清規格，不靠「多跑幾次/多開 agent」掩蓋規格缺口。</li><li><strong>R1.2 Ask-rate 校準</strong>（承 AB4.0）：等價瑣碎選擇（命名/格式/預設值）自決並一句註明；scope 變更/破壞性動作必問。<strong>論文背書缺口</strong>：此校準目前無論文直接支撐，是工程經驗（Opus 4.8 官方 nudge −12pp over-reach），標 <strong>工程經驗 MEDIUM</strong>。</li></ul><p><strong>可機械驗證</strong>：實作前輸出是否含「詮釋 ≤2 句 + 假設 + 多解釋列選項」三要素（grep transcript）。</p><p><strong>反模式</strong>：用「直接做」掩蓋規格缺口；把「不可逆動作」（DELETE/DROP/prod deploy）也自決。</p><hr><h3 id="r2-—-simplicity-first-深化-情境化-記憶庫的-speculative-accumulation" tabindex="-1">R2 — Simplicity First（深化：情境化 + 記憶庫的 speculative accumulation） <a class="header-anchor" href="#r2-—-simplicity-first-深化-情境化-記憶庫的-speculative-accumulation" aria-label="Permalink to &quot;R2 — Simplicity First（深化：情境化 + 記憶庫的 speculative accumulation）&quot;">​</a></h3><p><strong>原則</strong>：最小能解決問題的碼；不投機加 feature、不為單次使用抽象。</p><p><strong>論文深化</strong>：</p><ul><li><strong>Dynamic Cheatsheet Curator 寫入前評估「有用性與可遷移性」，低品質不寫入</strong>（Direct）：DC 把 R2 從「碼的簡潔」延伸到「<strong>記憶庫的簡潔</strong>」。<strong>一句零 hedge</strong>：記憶庫不累積所有輸出，只存真正有複用價值的 snippet，直接防止記憶庫膨脹與品質退化。</li><li><strong>DC 小模型（GPT-4o-mini）記憶庫被錯誤策略污染、受益反轉</strong>（Direct，數字親驗：DC Claude 3.5 在 AIME 2024 23.3%→50.0%，但小模型受益有限）：speculative accumulation 在記憶層的代價比在碼層更隱蔽。</li><li><strong>Anthropic「Teams frequently make this choice incorrectly」</strong>（Direct）：錯置委派（為複雜任務自動拆 agent）製造 coordination overhead 抵消平行收益。<strong>一句零 hedge</strong>：Rule of 3 有 multi-agent 版本——不因任務看起來複雜就自動拆 agent。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R2.1 記憶層 Simplicity</strong>：寫入持久記憶/cheatsheet 前先問「這條有跨任務複用價值嗎」，無 → 不寫（防 DC 觀察到的記憶污染）。</li><li><strong>R2.2 委派 Simplicity</strong>：不因任務複雜就自動 fan-out；委派門檻（≥10 檔/&gt;20 tool call/≥3 獨立子任務）未達 → 主對話直接做。</li><li><strong>R2.3 情境化例外</strong>（補 Mnilax 斷裂點 4）：prototype / spike 階段正當需要 speculative scaffold 探方向時，Simplicity 不過火——<strong>明示標註「prototype 模式」</strong>，達方向後再砍。</li></ul><p><strong>可機械驗證</strong>：diff 行數 vs 任務最小解的比值；持久記憶寫入是否附「複用理由」一行。</p><p><strong>反模式</strong>：為「未來可能需要」鋪設；把每次互動都存進記憶庫；prototype 階段過早 over-engineer 或 production 階段假裝 prototype 放縱。</p><hr><h3 id="r3-—-surgical-changes-深化-cache-前綴穩定性-prompt-層的外科精度" tabindex="-1">R3 — Surgical Changes（深化：cache 前綴穩定性 = prompt 層的外科精度） <a class="header-anchor" href="#r3-—-surgical-changes-深化-cache-前綴穩定性-prompt-層的外科精度" aria-label="Permalink to &quot;R3 — Surgical Changes（深化：cache 前綴穩定性 = prompt 層的外科精度）&quot;">​</a></h3><p><strong>原則</strong>：只動必須動的；不順手改周邊、不重構沒壞的；改動造成的孤兒才清。</p><p><strong>論文深化</strong>：</p><ul><li><strong>Don&#39;t Break the Cache（arXiv 2601.06007）：prompt caching 在 agentic workflow 降 API 成本 41–80%，但動態內容造成的 cache invalidation 是關鍵風險；建議 system-prompt-only caching（Claude Sonnet 4.5 達 78.5% cost reduction / 22.9% TTFT improvement）</strong>（Direct，數字親驗 <code>2601-06007.md</code>）：<strong>一句零 hedge</strong>：快取前綴設計若把動態內容放前段污染靜態邊界，引發的成本劣化與「改動污染周邊代碼」同構——靜態前綴穩定性是 surgical 精度在 prompt 層的投影。〔修正：原稿誤植「TTFT 13–31% / 500+ session」，論文原數字為 22.9% TTFT / 78.5% cost（system-prompt-only），已更正。〕</li><li><strong>SWE-agent「Cascading Failed Edits」是失敗分布最大宗（首次失敗恢復率 90.5% → 追加失敗後 57.2%）</strong>（Analogous）：<strong>一句零 hedge</strong>：過寬/缺理解的編輯引發連鎖失敗，與「bug fix 順手清理」引發的周邊污染機制相同；surgical 邊界一旦破壞，後果指數惡化（90.5%→57.2% 量化此惡化）。</li><li><strong>MemoryBank Ebbinghaus 衰減 + Reflexion episodic-only（只追加不修改）</strong>（Analogous）：記憶寫入應最小化、append-only（不就地改寫現有記憶），與 R3「只動最小範圍」平行。Reflexion 此設計在 HumanEval 達 91%。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R3.1 Prompt-層 Surgical</strong>：CLAUDE.md / system prompt 的靜態前綴 mid-session 不動（破快取 = full cache miss）；動態狀態經 <code>&lt;system-reminder&gt;</code> 注入 TAIL，不寫進靜態前綴。</li><li><strong>R3.2 記憶 append-only</strong>：對持久記憶優先 append 不就地改寫；需修正舊記憶時保留原條目作 rollback（承 Operational Layer）。</li></ul><p><strong>可機械驗證</strong>：每行改動可追溯到任務要求（grep）；<code>cache_hit_rate = cache_read / input_tokens &gt; 0.7</code>（長跑 session）；記憶寫入是 append 或有 rollback 備份。</p><p><strong>反模式</strong>：mid-session 改 CLAUDE.md/切 model/增刪 tool（四大破快取源）；就地覆蓋舊記憶無備份。</p><hr><h3 id="r4-—-goal-driven-execution-深化-reflexion-voyager-react-的迭代演化迴圈" tabindex="-1">R4 — Goal-Driven Execution（深化：Reflexion/Voyager/ReAct 的迭代演化迴圈） <a class="header-anchor" href="#r4-—-goal-driven-execution-深化-reflexion-voyager-react-的迭代演化迴圈" aria-label="Permalink to &quot;R4 — Goal-Driven Execution（深化：Reflexion/Voyager/ReAct 的迭代演化迴圈）&quot;">​</a></h3><p><strong>原則</strong>：定義可觀測成功條件，迭代到達標而非走步驟；完成條件必須可機械驗證。</p><p><strong>論文深化</strong>（這是「LLM 自我演化」維度的主接地點）：</p><ul><li><strong>ReAct Thought-Action-Observation 交錯（ALFWorld +34%、WebShop +10% vs RL baseline）</strong>（Direct）：<strong>一句零 hedge</strong>：ReAct 的 iterative action-observation loop 是 R4「成功條件可機械驗證、迭代至達標」的 harness 實作；無 Observation 接地 = 目標狀態不可觀測。Act-only（無 reasoning trace）在 long-horizon 系統性低於 ReAct，量化了「無迭代迴圈」的代價。</li><li><strong>Reflexion：失敗後生成語言反思存入 episodic buffer，下次注入（HumanEval pass@1 91.0% &gt; GPT-4 80.1%；ALFWorld 97% vs ReAct 53%）</strong>（Direct）：<strong>一句零 hedge</strong>：反思機制使代理人每次嘗試後明確「驗證失敗原因 → 迭代」而非盲目重試，是 R4「迭代到達標」的機械實現。</li><li><strong>Voyager：技能生成後在環境實際執行驗證，通過才入庫（技術樹 15.3× 快）</strong>（Direct）：<strong>一句零 hedge</strong>：成功條件是「環境中可執行並達成目標」這種可機械驗證的條件，而非 LLM 自評。</li><li><strong>Reflexion 的 Evaluator 元件是反思的前提</strong>（Direct，亦接地 R9）：<strong>一句零 hedge</strong>：沒有獨立 evaluator 給出明確失敗訊號，LLM 就無法生成有意義的反思——可驗證的成功條件是自我演化的先決條件。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R4.1 反思迴圈（自我演化）</strong>：task 失敗 → 生成結構化反思（失敗模式 + 修正假設）→ 下次同類任務注入。<strong>前提</strong>：反思必須由獨立 evaluator 的失敗訊號觸發，不由 LLM 自評觸發（否則是無根據自我反思）。</li><li><strong>R4.2 技能/洞見入庫門檻</strong>：成功經驗要進持久庫，須有可機械驗證的通過證明（碼執行/benchmark/對比軌跡），不接受文字自評（Voyager 原則）。</li><li><strong>R4.3 完成條件機械化</strong>：「make it work」是弱條件 → 卡在「下一步」；強條件（測試/healthcheck/特定輸出）才能獨立 loop。</li></ul><p><strong>可機械驗證</strong>：開工前是否寫下可機械驗證的成功條件；宣告完成前是否展示前 5 行/後 5 行輸出（R12 連動）；反思是否由 evaluator 失敗訊號觸發。</p><p><strong>反模式</strong>：把「tests pass」當唯一目標寫淺測試（→ R9）；LLM 自評觸發的反思（無 evaluator）；無 Observation 接地的盲目重試。</p><hr><h3 id="r5-—-use-the-model-for-judgment-code-for-decisions-深化-routellm-dc-的確定性化" tabindex="-1">R5 — Use the Model for Judgment, Code for Decisions（深化：RouteLLM/DC 的確定性化） <a class="header-anchor" href="#r5-—-use-the-model-for-judgment-code-for-decisions-深化-routellm-dc-的確定性化" aria-label="Permalink to &quot;R5 — Use the Model for Judgment, Code for Decisions（深化：RouteLLM/DC 的確定性化）&quot;">​</a></h3><p><strong>原則</strong>：LLM 只做判斷（分類/摘要/提取/生成）；確定性碼做決定（路由/重試/status code/數學）。</p><p><strong>論文深化</strong>（這是最容易被 LLM 自己違反的規則，論文證據最硬）：</p><ul><li><strong>RouteLLM：學習型 router 比 LLM 自判路由節省 3.66× 成本，MT Bench 減少 GPT-4 呼叫 75% 仍恢復 95% 性能，routing overhead &lt; 0.4%</strong>（Direct）：<strong>一句零 hedge</strong>：RouteLLM 明確比較「LLM-as-router vs learned-classifier-as-router」，分類器全面勝出——把路由從 LLM 搬到確定性分類器的工程成本極低（&lt; 0.4% overhead），沒有理由不做。</li><li><strong>Dynamic Cheatsheet Game of 24：10%→99%（LLM 判斷「要不要用 Python 暴力解」，確定性 code 做實際計算）</strong>（Direct）：<strong>一句零 hedge</strong>：把計算交給 LLM 是 baseline 停在 10% 的根因；路由「要不要用工具」= 判斷（LLM），執行計算 = 確定性（Python），這是 R5 的教科書案例。</li><li><strong>MemGPT function chaining：LLM 決定「是否還需更多 context 再回應」（判斷），程式執行 page-in（確定性）</strong>（Direct）：記憶操作層的 R5 體現。</li><li><strong>Voyager 代碼技能（確定性）vs「該召用哪個技能」（LLM 判斷）明確分離</strong>（Direct）。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R5.1 路由確定性化</strong>：模型/工具/重試路由用學習型分類器或規則，不用 LLM 即時判斷（RouteLLM 證據）。</li><li><strong>R5.2 記憶操作分層</strong>：「是否 page-in / 是否該整合記憶」是判斷（LLM 觸發）；「執行 page-in / 寫入記憶」是確定性（程式執行）。</li><li><strong>R5.3 工具呼叫 vs 自算</strong>：可被工具/程式精確算出的（數學、解析、轉換）一律交工具，LLM 只決定「要不要用」（DC 證據）。</li></ul><p><strong>可機械驗證</strong>：路由/重試/status-code 處理是否出現 LLM 呼叫（grep；應為 0）；計算密集任務是否委派工具。</p><p><strong>反模式</strong>：用 Claude「決定 503 是否重試」（Mnilax R5 the moment，request body 變決策 context → 隨機 policy）；讓 LLM 做算術。</p><hr><h3 id="r6-—-token-budgets-are-not-advisory-深化-memgpt-分層記憶-lost-in-the-middle" tabindex="-1">R6 — Token Budgets Are Not Advisory（深化：MemGPT 分層記憶 + Lost-in-the-Middle） <a class="header-anchor" href="#r6-—-token-budgets-are-not-advisory-深化-memgpt-分層記憶-lost-in-the-middle" aria-label="Permalink to &quot;R6 — Token Budgets Are Not Advisory（深化：MemGPT 分層記憶 + Lost-in-the-Middle）&quot;">​</a></h3><p><strong>原則</strong>：per-task 4,000 / per-session 30,000 token 硬預算；接近預算 → 摘要重啟，不硬推；浮現超標 &gt; 靜默超支。</p><p><strong>論文深化</strong>（這是「Memory Management」+「Context Management」維度的主接地點）：</p><ul><li><strong>MemGPT：context 滿時強制 evict，未 page-in 的資訊在決策期間不可見（DMR 92.5% vs 固定 context 32.1%，+28–60pp）</strong>（Direct）：<strong>一句零 hedge</strong>：上下文預算硬性邊界直接決定代理人當前步驟能「看到」什麼，超出即資訊丟失——R6 的 budget 不只是省錢，是決定可見性。MemGPT 把 context 當 OS 主記憶、外部記憶當磁碟，用 function call page in/out，是 R6 的架構化實現。</li><li><strong>Lost-in-the-Middle（arXiv 2307.03172）：中間位置準確率下降 30%+，1M 名義 context 可靠工作區實際約 64K–128K</strong>（Direct）：<strong>一句零 hedge</strong>：context 名義大 ≠ 可用大；在 1M 中間段放關鍵資訊等於靜默丟棄——R6 的 budget 意識必須含<strong>位置意識</strong>（HEAD 放原始目標 / TAIL 放最新工具輸出 / 中間放動態狀態）。</li><li><strong>MemoryBank Ebbinghaus 衰減曲線（R = e^(-t/S)）決定何時棄舊 context</strong>（Analogous）：頻繁召回的記憶強度 S 增大，長期未用的衰減後淡出——提供「何時 evict」的機制借鏡。</li><li><strong>ACE incremental delta updates 達 91.8% input tokens served from KV cache；移除 delta → context collapse（「sharp performance declines as accumulated knowledge is overwritten」）；agents +10.6% / finance +8.6%</strong>（Direct，數字親驗 <code>2510-04618.md</code>）：<strong>一句零 hedge</strong>：每次 full-rewrite 而非 delta 是 token 爆炸與 context collapse 的直接操作來源，ACE 的 91.8% KV reuse 是 R6 的量化錨點。〔修正：原稿誤植「帳單 −82.6%」，論文無此數字，已移除——abstract 僅稱「significantly reducing adaptation latency and rollout cost」。〕</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R6.1 分層記憶卸載</strong>：context 達 70% → 觸發 page-out（把舊狀態寫外部記憶，只留索引）；不在單一 context 裡硬撐到爆。</li><li><strong>R6.2 位置意識</strong>：原始目標放 HEAD、最新工具輸出放 TAIL、動態狀態放中間（NLAH 原則 + Lost-in-the-Middle 接地）。</li><li><strong>R6.3 Delta 不 full-rewrite</strong>：更新長文/記憶用 delta，不整篇重寫（ACE 證據，亦護 prompt cache）。</li></ul><p><strong>可機械驗證</strong>：session token 用量 <code>/usage</code> vs 預算；compact 觸發點（長 agentic 30–35% 主動）；<code>cache_hit_rate &gt; 0.7</code>。</p><p><strong>反模式</strong>：90 分鐘 debug 在同一 8KB error 上空轉（Mnilax R6 the moment）；關鍵資訊埋 context 中間段；每次 full-rewrite 長文。</p><hr><h3 id="r7-—-surface-conflicts-don-t-average-them-深化-mast-inter-agent-misalignment-辯論-echo-chamber" tabindex="-1">R7 — Surface Conflicts, Don&#39;t Average Them（深化：MAST Inter-Agent Misalignment + 辯論 echo-chamber） <a class="header-anchor" href="#r7-—-surface-conflicts-don-t-average-them-深化-mast-inter-agent-misalignment-辯論-echo-chamber" aria-label="Permalink to &quot;R7 — Surface Conflicts, Don&#39;t Average Them（深化：MAST Inter-Agent Misalignment + 辯論 echo-chamber）&quot;">​</a></h3><p><strong>原則</strong>：兩個矛盾 pattern 不靜默選、不混用；挑一個（較新/較測過）說明理由，另一個標記清理。</p><p><strong>論文深化</strong>（這是「Agent Teams」維度的主接地點）：</p><ul><li><strong>MAST「Inter-Agent Misalignment」整類（coordinator 指令漂移、資訊傳遞失真、Ignored other agent&#39;s input）</strong>（Analogous）：<strong>一句零 hedge</strong>：矛盾被平均化（agent 各自解讀指令取交集）是 R7「靜默選擇」在分散式系統的放大版；structured handoff + confirmation 是 R7 在多 agent 層的落地形式。</li><li><strong>多 agent 辯論：GSM8K +8pp / MMLU +7.2pp，但 echo-chamber 固化錯誤是主要風險</strong>（Analogous，代價 2.5–5× token）：<strong>一句零 hedge</strong>：多視角交叉驗證能提升正確率，但若各方互相強化同一錯誤（echo-chamber），等於把矛盾平均掉——R7 要求矛盾浮現而非收斂到舒適共識。</li><li><strong>HippoRAG 知識圖譜：孤立 chunk 無法回答關聯問題，矛盾事實若不顯式連結就無法在檢索時被發現</strong>（Inferential）：<strong>一句零 hedge（標 Inferential，需跳躍）</strong>：記憶條目間的矛盾若不顯式建立連結，檢索時不會浮現——與 R7「不靜默選擇矛盾」目標一致，但「知識圖譜檢索」到「codebase pattern 衝突」的連結需要推理跳躍，故降級。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R7.1 多來源矛盾浮現</strong>：sub-agent / 多視角輸出矛盾時，不收斂到「都滿足」的平均解，明列矛盾交主對話決策（child 不 self-resolve 矛盾）。</li><li><strong>R7.2 記憶/洞見遷移前判矛盾</strong>：跨任務注入洞見前判斷是否與當前任務矛盾，不靜默混用（ExpeL 任務相似度門控）。</li></ul><p><strong>可機械驗證</strong>：是否寫 <code>TODO(conflict): chose A over B; reason …; remove B before &lt;milestone&gt;</code>；矛盾是否被明列而非收斂。</p><p><strong>反模式</strong>：寫同時滿足兩種 error-handling pattern 的碼（Mnilax R7 the moment，雙重 handler 吞兩次 error）；echo-chamber 式共識。</p><hr><h3 id="r8-—-read-before-you-write-深化-context-failure-是新失敗主因-swe-agent-定位先於編輯" tabindex="-1">R8 — Read Before You Write（深化：context failure 是新失敗主因 + SWE-agent 定位先於編輯） <a class="header-anchor" href="#r8-—-read-before-you-write-深化-context-failure-是新失敗主因-swe-agent-定位先於編輯" aria-label="Permalink to &quot;R8 — Read Before You Write（深化：context failure 是新失敗主因 + SWE-agent 定位先於編輯）&quot;">​</a></h3><p><strong>原則</strong>：改動前讀目標 exports + 直接 caller + 共用 utility；不懂現有結構先問。「Looks orthogonal」最危險。</p><p><strong>論文深化</strong>：</p><ul><li><strong>SWE-agent「find_file / search_dir 先於 edit」+ Zoom-in（dir→file→line）；跳過定位直接 edit = 23.4% cascading failure</strong>（Direct）：<strong>一句零 hedge</strong>：「Reproduction-first（create, edit, python）」是機械化的 R8 執行，跳過定位直接 edit 的失敗代價被量化為 23.4% cascading failure。</li><li><strong>「Most agent failures are now context failures, not model failures」（Anthropic/LangChain/Manus 三方共識）</strong>（Analogous）：<strong>一句零 hedge</strong>：先讀 exports + caller + shared utility 在 context engineering 語義下等價於「先確認 context 邊界再寫入新資訊」；錯置的 context write 與未讀就改一樣破壞上游依賴。</li><li><strong>四大破快取源（mid-session 切 model / 增刪 tool / 改 system prompt / 改 thinking 參數）</strong>（Direct，接地 R8 的「先確認影響再動」）：<strong>一句零 hedge</strong>：任何 system prompt 修改前必先確認快取拓撲影響，「看起來正交」的模型切換實際上使整個前綴快取全失效。</li><li><strong>CoALA：Working Memory（= context window）寫入前必先讀現有記憶狀態</strong>（Direct）：對外部記憶庫寫入前，先讀相關條目確認重複/衝突（A-MEM Zettelkasten 互聯機制）。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R8.1 記憶寫入先讀</strong>：對持久記憶任何寫入前，用當前 query 做 similarity search 確認無重複/衝突再決定 append 或更新。</li><li><strong>R8.2 快取拓撲先讀</strong>：改 system prompt / 切 model / 增刪 tool 前先確認對 cache_hit_rate 的影響。</li></ul><p><strong>可機械驗證</strong>：是否先讀 exports/caller/utility（transcript）；記憶寫入前是否有 similarity check。</p><p><strong>反模式</strong>：在沒讀過的同功能函式旁加重複函式（Mnilax R8 the moment，import order 讓新的覆蓋當了 6 個月 source of truth 的舊的）。</p><hr><h3 id="r9-—-tests-verify-intent-not-just-behavior-深化-evaluator-是演化先決-辯論交叉驗證" tabindex="-1">R9 — Tests Verify Intent, Not Just Behavior（深化：Evaluator 是演化先決 + 辯論交叉驗證） <a class="header-anchor" href="#r9-—-tests-verify-intent-not-just-behavior-深化-evaluator-是演化先決-辯論交叉驗證" aria-label="Permalink to &quot;R9 — Tests Verify Intent, Not Just Behavior（深化：Evaluator 是演化先決 + 辯論交叉驗證）&quot;">​</a></h3><p><strong>原則</strong>：測試要能在業務邏輯改變時失敗；能通過任何實作的測試 = 沒測試；mock 外部邊界非業務核心。</p><p><strong>論文深化</strong>：</p><ul><li><strong>MAST「Task Verification」整類（Premature termination / No verification / Incorrect verification）是最難自動修復的類別</strong>（Direct）：<strong>一句零 hedge</strong>：MAST 原文「allowing errors to propagate undetected」直接映射 R9「假測試」與 R12「幻覺式完成」；Incorrect verification（驗證方法本身錯）正是 R9 的「假測試」。</li><li><strong>Reflexion Evaluator：無獨立失敗訊號就無法生成有意義反思</strong>（Direct，亦接地 R4）：<strong>一句零 hedge</strong>：可驗證的成功條件是自我演化的先決條件——R9 的「測試驗證意圖」是 R4 反思迴圈能運作的前提。</li><li><strong>多 agent 辯論交叉驗證 vs echo-chamber</strong>（Analogous）：<strong>一句零 hedge</strong>：多視角交叉驗證 = R9「測試要能在業務邏輯改變時失敗」；echo-chamber 等價於「通過任何實作的測試 = 假測試」。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R9.1 Evaluator 獨立性</strong>：成功條件的判定器（測試/healthcheck/對比）必須獨立於被測對象，不能由 LLM 自評充當（否則 R4 反思失去根據）。</li><li><strong>R9.2 演化入庫驗證</strong>：洞見/技能進持久庫前須通過可機械驗證（連動 R4.2）。</li></ul><p><strong>可機械驗證</strong>：測試是否會在業務邏輯 mutation 時失敗（mutation testing）；evaluator 是否獨立於被測對象。</p><p><strong>反模式</strong>：12 個 auth 測試全過但函式回傳常數（Mnilax R9 the moment）；LLM 自評當 evaluator。</p><hr><h3 id="r10-—-checkpoint-after-every-significant-step-深化-react-observation-記憶整合門控" tabindex="-1">R10 — Checkpoint After Every Significant Step（深化：ReAct Observation + 記憶整合門控） <a class="header-anchor" href="#r10-—-checkpoint-after-every-significant-step-深化-react-observation-記憶整合門控" aria-label="Permalink to &quot;R10 — Checkpoint After Every Significant Step（深化：ReAct Observation + 記憶整合門控）&quot;">​</a></h3><p><strong>原則</strong>：每完成重要步驟輸出 1 句 <code>[Checkpoint] 做了X/驗了Y/剩Z</code>；無法描述當前狀態時停下重述。</p><p><strong>論文深化</strong>（這是「Context Management」+「Memory consolidation」維度的接地點）：</p><ul><li><strong>ReAct Thought-Action-Observation triple 克服 CoT 幻覺傳播</strong>（Direct）：<strong>一句零 hedge</strong>：每個 Observation 迫使模型接地當前真實狀態、不在幻覺狀態上續推——這是 R10「無法描述當前狀態時停下」的形式化；Thought-Action-Observation = checkpoint loop 是 harness 層公認結構。</li><li><strong>Summarization 資訊保留率僅 37%（Factory.ai，MEDIUM）</strong>（Analogous）：<strong>一句零 hedge</strong>：compact 後若無 checkpoint 驗證（任務目標仍在？安全紅線仍在？），37% 資訊損失會變成 loss-of-state 在損壞狀態上續跑——R10 正是緩解此損失的機制。</li><li><strong>SCM/MemoryBank 記憶控制器顯式門控「何時整合」+ Survey 2404.13501「整合是性能退化主要來源」+ Human→AI Survey「整合應由重要性篩選觸發，非自動」</strong>（Direct）：<strong>一句零 hedge</strong>：記憶整合（consolidation）等同 checkpoint 寫入，必須在顯式觸發時才執行，不應每次互動後自動發生（自動整合 = 靜默失敗風險）。</li><li><strong>ExpeL offline 批量整合 vs 即時整合</strong>（Direct）：offline consolidation 等同多個 checkpoint 後才整合，防即時整合的噪聲退化。</li><li><strong>MAST「Step repetition / Loss of conversation history」</strong>（Direct）：無法判斷已在何處 → 重複執行；R10 狀態追蹤防範。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R10.1 Checkpoint 含記憶寫入</strong>：checkpoint 不只記「做了什麼」，也記「寫入 episodic memory 什麼」（task ID + 成功/失敗 + 關鍵觀察，非完整軌跡）。</li><li><strong>R10.2 整合門控</strong>：記憶 consolidation（episodic→semantic）只在顯式觸發或 N 個 checkpoint 後執行，禁自動；整合前保留原 episodic 作 rollback。</li><li><strong>R10.3 Compact 後自檢</strong>：compact/summarize 後驗「任務目標/安全紅線/最近工具結果未失真」，任一失 → rewind（緩解 37% 損失）。</li></ul><p><strong>可機械驗證</strong>：每步是否輸出 checkpoint 句；compact 後是否跑三項自檢；整合是否門控（非自動）。</p><p><strong>反模式</strong>：6 步 refactor 第 4 步壞了還做完 5、6（Mnilax R10 the moment）；自動記憶整合無 rollback。</p><hr><h3 id="r11-—-match-the-codebase-s-conventions-深化-多-codebase-一致性-有害慣例不-silent-fork" tabindex="-1">R11 — Match the Codebase&#39;s Conventions（深化：多 codebase 一致性 + 有害慣例不 silent fork） <a class="header-anchor" href="#r11-—-match-the-codebase-s-conventions-深化-多-codebase-一致性-有害慣例不-silent-fork" aria-label="Permalink to &quot;R11 — Match the Codebase&#39;s Conventions（深化：多 codebase 一致性 + 有害慣例不 silent fork）&quot;">​</a></h3><p><strong>原則</strong>：codebase 既有慣例 &gt; 個人偏好；不確定跟隨最近 3 commit；有害慣例明說另開議題，不 silent fork。</p><p><strong>論文深化</strong>：</p><ul><li><strong>Mnilax 斷裂點 2（多 codebase 一致性）</strong>：「match existing style」假設只有一種 style，monorepo 12 服務時隨機挑或平均（作者自報 LOW，但與 R7 同構）。</li><li><strong>MemGPT/CoALA Procedural Memory（可執行 artifact 形式儲存慣例）</strong>（Inferential）：<strong>一句零 hedge（標 Inferential）</strong>：把慣例存成可執行/可檢查的 artifact（lint config、template）比存成文字描述更不易漂移——但「procedural memory」到「codebase convention」的連結需推理跳躍，故降級。</li><li><strong>capability-agnostic 措辭</strong>（Mnilax what-didn&#39;t-work #3，作者自報）：「match the codebase&#39;s enforced style」優於「always use eslint」（工具沒裝就靜默失敗）。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R11.1 多 codebase 範圍判定</strong>：monorepo / 多服務時，先判定當前檔案所屬服務的慣例（最近 commit + 該目錄 config），不跨服務平均。</li><li><strong>R11.2 慣例存成可檢查 artifact</strong>：能用 lint/template/config 表達的慣例優先存成 artifact，不只寫文字（降漂移）。</li></ul><p><strong>可機械驗證</strong>：新碼風格 vs 該目錄最近 3 commit 的一致性；是否 silent fork（無 issue 記錄就引入新 pattern）。</p><p><strong>反模式</strong>：把 React hooks 引進 class-component codebase（Mnilax R11 the moment，破壞 componentDidMount 測試模式）；依賴可能不存在的工具。</p><hr><h3 id="r12-—-fail-loud-深化-靜默失敗是最貴的-記憶污染的隱蔽性" tabindex="-1">R12 — Fail Loud（深化：靜默失敗是最貴的 + 記憶污染的隱蔽性） <a class="header-anchor" href="#r12-—-fail-loud-深化-靜默失敗是最貴的-記憶污染的隱蔽性" aria-label="Permalink to &quot;R12 — Fail Loud（深化：靜默失敗是最貴的 + 記憶污染的隱蔽性）&quot;">​</a></h3><p><strong>原則</strong>：不確定是否成功就明說；「migration completed」若靜默跳過紀錄是錯的；截斷必標示。</p><p><strong>論文深化</strong>：</p><ul><li><strong>MAST「Information withholding / Premature termination / No verification」</strong>（Direct）：<strong>一句零 hedge</strong>：agent 隱藏部分失敗（Information withholding）與 R12「不藏部分失敗」直接對應；Premature termination（未完成即宣告完成）= R12「幻覺式完成」。</li><li><strong>DC 記憶污染：策略看似存入，實際引導後續決策時引入錯誤（小模型受益反轉）</strong>（Direct）：<strong>一句零 hedge</strong>：記憶污染是靜默失敗——需要顯式的記憶品質指標讓退化可見。</li><li><strong>Survey 2404.13501：長時運行後性能退化，根源是整合的資訊丟失</strong>（Analogous）：<strong>一句零 hedge</strong>：記憶退化是靜默失敗的典型形態——系統繼續運作但輸出品質持續下降，需要可觀測退化指標（如召回準確率 benchmark）讓失敗顯露。</li><li><strong>SWE-agent linting guardrail：no linting → −3pp</strong>（Direct）：<strong>一句零 hedge</strong>：linting 在語法錯誤時立即阻斷而非靜默接受，是 R12 的工具層實現，−3pp 量化了靜默失敗的代價。</li></ul><p><strong>延伸的新子條</strong>：</p><ul><li><strong>R12.1 記憶退化可觀測</strong>：持久記憶/cheatsheet 須有品質指標（召回準確率/污染檢查），退化時 fail loud 而非靜默劣化。</li><li><strong>R12.2 PGE（Proactive Generation &amp; Evaluation）</strong>：完成後跑 healthcheck 或委派 review，不接受口頭自評；略過步驟必明示。</li><li><strong>R12.3 截斷標示</strong>：讀 &gt;200 行檔分段報「N-M/X 行，剩 Y」；搜尋超限標 <code>[CONTEXT BOUNDARY]</code>，靜默截斷禁止。</li></ul><p><strong>可機械驗證</strong>：完成宣告前是否展示驗證輸出前5/後5行；migration/批次是否報「成功 N / 跳過 M / 原因」；截斷是否標示。</p><p><strong>反模式</strong>：migration「completed successfully」靜默跳過 14% 紀錄（Mnilax R12 the moment，11 天後才發現）；記憶靜默劣化。</p><hr><h2 id="_4-跨規則主題-harness-loop-與-llm-自我演化的整合" tabindex="-1">4. 跨規則主題：Harness Loop 與 LLM 自我演化的整合 <a class="header-anchor" href="#_4-跨規則主題-harness-loop-與-llm-自我演化的整合" aria-label="Permalink to &quot;4. 跨規則主題：Harness Loop 與 LLM 自我演化的整合&quot;">​</a></h2><p>本研究的請求明確要求準則「符合 Harness Loop」並涵蓋「LLM 自身的演化能力」。這兩者不是新規則，而是<strong>貫穿 R4/R9/R10/R12 的元迴圈</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OBSERVE  ← R10 Checkpoint（觀測當前狀態）</span></span>
<span class="line"><span>IDENTIFY ← R1 Think（顯露問題/假設）</span></span>
<span class="line"><span>PROPOSE  ← R2 Simplicity（最小提案）</span></span>
<span class="line"><span>TEST     ← R9 Evaluator（獨立驗證，Reflexion 先決條件）</span></span>
<span class="line"><span>APPLY    ← R3 Surgical（最小改動）+ R12 gate（破壞性前確認）</span></span>
<span class="line"><span>RECORD   ← R4.1 反思迴圈 + R10.1 記憶寫入（演化的持久化）</span></span></code></pre></div><p><strong>論文接地的演化迴圈</strong>（信度分級）：</p><ul><li><strong>Reflexion</strong>（Direct）：失敗 → 語言反思 → episodic buffer → 下次注入。對應 RECORD → OBSERVE 的閉環。</li><li><strong>Voyager</strong>（Direct）：成功技能環境驗證後入庫，可組合呼叫。對應 APPLY → RECORD 的技能累積。</li><li><strong>ExpeL</strong>（Direct）：offline 批量對比成功/失敗軌跡提取洞見。對應 RECORD 的離線整合（防即時整合退化）。</li><li><strong>Dynamic Cheatsheet</strong>（Direct）：test-time learning，Curator 門控寫入。對應 RECORD 的品質門控。</li></ul><p><strong>演化的安全邊界</strong>（避免「自我演化」變成「自我污染」，DC 小模型污染證據）：</p><ol><li>反思只由獨立 evaluator 失敗訊號觸發，不由 LLM 自評觸發（R9.1）。</li><li>洞見入庫須通過可機械驗證（R4.2 / R9.2）。</li><li>整合門控、非自動（R10.2）。</li><li>記憶退化可觀測（R12.1）。</li><li>高錯誤率場景禁自動寫入（DC 證據）。</li></ol><hr><h2 id="_5-與社群-官方最佳實踐的對照" tabindex="-1">5. 與社群/官方最佳實踐的對照 <a class="header-anchor" href="#_5-與社群-官方最佳實踐的對照" aria-label="Permalink to &quot;5. 與社群/官方最佳實踐的對照&quot;">​</a></h2><h3 id="_5-1-官方-anthropic-指引-high-信度-強化的規則" tabindex="-1">5.1 官方 Anthropic 指引（HIGH 信度）強化的規則 <a class="header-anchor" href="#_5-1-官方-anthropic-指引-high-信度-強化的規則" aria-label="Permalink to &quot;5.1 官方 Anthropic 指引（HIGH 信度）強化的規則&quot;">​</a></h3><table tabindex="0"><thead><tr><th>官方指引</th><th>強化規則</th><th>來源</th></tr></thead><tbody><tr><td>CLAUDE.md 目標 ≤200 行，過長 reduce adherence</td><td>R6</td><td>code.claude.com/docs/en/memory</td></tr><tr><td>CLAUDE.md 是 advisory，硬性執行用 hooks</td><td>R12</td><td>best-practices</td></tr><tr><td><code>.claude/rules/*.md</code> + <code>paths:</code> frontmatter conditional loading</td><td>R6 + R2</td><td>memory docs</td></tr><tr><td><code>/init</code> 生成後人工精簡</td><td>R8（先讀 codebase 再寫規則）</td><td>best-practices</td></tr><tr><td>「去掉這條 Claude 會犯錯嗎？否→刪」</td><td>R3</td><td>best-practices</td></tr><tr><td>Writer/Reviewer 雙 session adversarial review</td><td>R9</td><td>best-practices</td></tr><tr><td>Subagents 隔離研究避免污染主 context</td><td>R5</td><td>best-practices</td></tr><tr><td><code>IMPORTANT</code>/<code>YOU MUST</code> 強調語提升遵循率</td><td>R1</td><td>官方文件原文</td></tr></tbody></table><h3 id="_5-2-12-條沒涵蓋的新洞見-官方-high" tabindex="-1">5.2 12 條沒涵蓋的新洞見（官方 HIGH） <a class="header-anchor" href="#_5-2-12-條沒涵蓋的新洞見-官方-high" aria-label="Permalink to &quot;5.2 12 條沒涵蓋的新洞見（官方 HIGH）&quot;">​</a></h3><ol><li><strong>Prompt caching × CLAUDE.md 靜態前綴</strong>：CLAUDE.md 是 session 內最穩定快取前綴，mid-session 編輯不生效也不破壞快取；cache hit rate 是 Anthropic SEV 監控指標 → 已整合進 R3.1 / R6.3 / R8.2。</li><li><strong><code>claudeMdExcludes</code>（monorepo 多 team 污染）</strong>：其他 team 的 CLAUDE.md 會被自動載入，用 <code>settings.local.json</code> glob 排除 → 整合進 R11.1（多 codebase）。</li><li><strong><code>&lt;!-- HTML comment --&gt;</code> zero-token 維護筆記</strong>：注入前剝除，不耗 context → R6 token 工具補充。</li><li><strong>官方 Auto Memory（v2.1.59+）</strong>：MEMORY.md 前 200 行/25KB session start 載入，Claude 自決何時寫 → 整合進 R10.1 記憶寫入。</li></ol><h3 id="_5-3-社群數字的信度-不可當共識" tabindex="-1">5.3 社群數字的信度（不可當共識） <a class="header-anchor" href="#_5-3-社群數字的信度-不可當共識" aria-label="Permalink to &quot;5.3 社群數字的信度（不可當共識）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>數字</th><th>信度</th><th>理由</th></tr></thead><tbody><tr><td>官方 200 行上限</td><td>HIGH</td><td>官方文件</td></tr><tr><td>AGENTS.md 2,500+ repo「中位 300-350 字最佳，&gt;1,000 字負相關」</td><td>MEDIUM</td><td>二手引用，原始方法論未公開</td></tr><tr><td>「150-200 instructions 後合規率劣化」（Jaroslawicz et al. 2025）</td><td>LOW</td><td>社群多次引用但原始論文連結無人提供，<strong>不以學術背書口吻引用</strong></td></tr><tr><td>Mnilax 41%→3% / Karpathy 41%→11%</td><td>LOW</td><td>作者自報，無控制組/同儕審查</td></tr><tr><td>lazy loading 省 40-70% token</td><td>LOW</td><td>部落格 tiktoken 計算，非官方計數器</td></tr></tbody></table><hr><h2 id="_6-改寫策略總結-→-配對-ruleset-檔的設計依據" tabindex="-1">6. 改寫策略總結（→ 配對 ruleset 檔的設計依據） <a class="header-anchor" href="#_6-改寫策略總結-→-配對-ruleset-檔的設計依據" aria-label="Permalink to &quot;6. 改寫策略總結（→ 配對 ruleset 檔的設計依據）&quot;">​</a></h2><ol><li><strong>保持 ≤12 條主規則</strong>（Mnilax 14 條崩潰證據）：所有深化以「子條 Rn.x」形式掛在主規則下，不新增主規則編號。子條是「同一注意力預算下的細化」，非競爭新規則。</li><li><strong>7 運行維度融入而非疊加</strong>：Memory→R6/R8/R10、演化→R4/R9、caching→R3/R6/R8、agent teams→R7、sub-agent→R2/R5、context→R6/R10、harness→R4/R10/R12。無獨立矩陣。</li><li><strong>每條深化保留信度標籤</strong>：Direct 證據寫進規則正文；Inferential 證據（HippoRAG→R7、procedural memory→R11）只在研究報告提及，不寫進可部署 ruleset（避免 Lesson 2026-06-04-G 過度延伸）。</li><li><strong>capability-agnostic + imperative + testable 措辭</strong>（Mnilax what-didn&#39;t-work #3/#5/#6）：每條附「可機械驗證條件」。</li><li><strong>Harness Loop 作元迴圈</strong>而非規則：OBSERVE→…→RECORD 對應 R10→…→R4.1，不佔規則編號。</li></ol><hr><h2 id="_7-參考論文-本研究實際引用" tabindex="-1">7. 參考論文（本研究實際引用） <a class="header-anchor" href="#_7-參考論文-本研究實際引用" aria-label="Permalink to &quot;7. 參考論文（本研究實際引用）&quot;">​</a></h2><blockquote><p><strong>親驗紀律說明</strong>：論文數字的初次 grep 由 researcher sub-agent 執行；其中<strong>載重數字</strong>（MemGPT 92.5%/32.1%、Reflexion 91.0%/80%、RouteLLM 3.66×/75%/95%、Voyager 15.3×/3.3×/2.3×、DC Game of 24 10%→99%、ACE 91.8% KV reuse、Don&#39;t Break Cache 41–80%/22.9% TTFT、MetaGPT 124.3 vs 248.9 tokens/loc、SWE-agent 23.4% cascading / 90.5%→57.2% recovery）由主對話<strong>二次 grep 親驗</strong>（依 workspace 鐵律「subagent verdict 非證據」），二次驗證攔截並修正 3 處 sub-agent 誤植（ACE −82.6% 不存在；Don&#39;t Break Cache TTFT 應為 22.9% 非 13–31%；MetaGPT −40% 為二手引用非該論文）。未經主對話二次 grep 的次要數字標 <strong>sub-agent grep（MEDIUM）</strong>。</p></blockquote><p><strong>Memory</strong>：MemGPT (2310.08560) · SCM (2304.13343) · MemoryBank (2305.10250) · HippoRAG (2405.14831) · A-MEM (2502.12110) · CoALA (2309.02427) · Survey-Memory (2404.13501) · Human→AI Memory Survey (2504.15965) <strong>Self-Evolution</strong>：Reflexion (2303.11366) · Voyager (2305.16291) · ExpeL (2308.10144) · Dynamic Cheatsheet (2504.07952) <strong>Agent Teams / Multi-Agent</strong>：MAST (2503.13657) · MetaGPT (2308.00352) · AutoGen (2308.08155) · AgentVerse (2308.10848) · ChatDev (2307.07924) · Multi-Agent Debate (2305.14325) · MultiAgentBench (2503.01935) <strong>Harness / Sub-Agent</strong>：ReAct (2210.03629) · SWE-agent (2405.15793) · RouteLLM (2406.18665) <strong>Context / Caching</strong>：Lost-in-the-Middle (2307.03172) · StreamingLLM (2309.17453) · SnapKV (2404.14469) · ACE (2510.04618) · Don&#39;t Break the Cache (2601.06007)</p><p><strong>第一來源</strong>：Karpathy CLAUDE.md（multica-ai/andrej-karpathy-skills，WebFetch 親驗）· Mnilax article（x.com/Mnilax/status/2053116311132155938，fxtwitter 親取 12,397 字元） <strong>官方文件</strong>：code.claude.com/docs/en/memory · /best-practices</p><hr><p><em>本報告為深度研究分析。可直接部署的精煉準則見配對檔 <code>2026-06-05-12-rule-deepened-ruleset.md</code>。</em></p>`,156)])])}const u=e(a,[["render",s]]);export{h as __pageData,u as default};
